window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7c63d6315fd9d2f7"]={"versions": [{"id": "FIG-7c63d6315fd9d2f7", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des Transportprotokoll-Ablaufs im AUTOSAR Classic Platform Kommunikationsstack. Das Diagramm spezifiziert die unsegmentierte 1:1-Punkt-zu-Punkt-Übertragung (Single Frame, SF) innerhalb des FlexRay Transport Protocol (FrTp) mit konfigurierter Empfangsbestätigung und Wiederholungsmechanismus (Acknowledgement with Retry) im Fehlerfall.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Kommunikationspartner und Protokolleinheiten (N-PDUs):</p>\n<ul class=\"fig-list\"><li><strong>Sender</strong>: Sendende FrTp-Instanz.\n</li><li><strong>Receiver</strong>: Empfangende FrTp-Instanz.\n</li><li><strong>SF (Single Frame)</strong>: Unsegmentierte Transport-PDU, übertragen vom Sender zum Receiver.\n</li><li><strong>AF (Acknowledgement Frame)</strong>: Bestätigungs-PDU vom Receiver zum Sender mit Ausprägung als negative Bestätigung (<code>AF (Negative Acknowledge)</code>) oder positive Bestätigung (<code>AF (Positive Acknowledge)</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Sequenzablauf stellt ein unsegmentiertes Übertragungsszenario mit anfänglichem Fehlschlag und erfolgreicher Wiederholung dar:</p>\n<ol class=\"fig-list\"><li>Sender initiiert die Übertragung mit einem ersten <code>SF</code> an den Receiver.\n</li><li>Receiver quittiert den fehlerhaften Empfang mit <code>AF (Negative Acknowledge)</code>.\n</li><li>Sender führt einen erneuten Sendeversuch (Retry) durch und sendet den <code>SF</code> erneut an den Receiver.\n</li><li>Receiver bestätigt den erfolgreichen Empfang des wiederholten Frames mit <code>AF (Positive Acknowledge)</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Ablauf definiert das deterministische Fehlerbehebungsverhalten bei aktivierter Bestätigung (<code>FrTpAckType = FRTP_ACK_WITH_RETRY</code>).</p>\n<ul class=\"fig-list\"><li>Bei Empfang von <code>AF (Negative Acknowledge)</code> muss die FrTp-Sendeseite den <code>SF</code> erneut übertragen, sofern die konfigurierte Maximalanzahl an Wiederholungsversuchen (<code>FRTP_MAX_RN</code>) noch nicht erreicht ist.\n</li><li>Erreicht die Anzahl der Wiederholungen <code>FRTP_MAX_RN</code> ohne positiven Empfang, wird der Übertragungsversuch abgebrochen und <code>PduR_FrTpTxConfirmation</code> bzw. <code>PduR_FrTpRxIndication</code> mit entsprechendem Fehlerergebnis an das PDU Router Modul (PduR) gemeldet.\n</li><li>Erst nach Empfang von <code>AF (Positive Acknowledge)</code> gilt die PDU als erfolgreich zugestellt.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-a6a742e0d6b34db2", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des Transportprotokoll-Ablaufs im AUTOSAR Classic Platform Kommunikationsstack. Das Diagramm spezifiziert die unsegmentierte 1:1-Punkt-zu-Punkt-Übertragung (Single Frame, SF) innerhalb des FlexRay Transport Protocol (FrTp) mit konfigurierter Empfangsbestätigung und Wiederholungsmechanismus (Acknowledgement with Retry) im Fehlerfall.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Kommunikationspartner und Protokolleinheiten (N-PDUs):</p>\n<ul class=\"fig-list\"><li><strong>Sender</strong>: Sendende FrTp-Instanz.\n</li><li><strong>Receiver</strong>: Empfangende FrTp-Instanz.\n</li><li><strong>SF (Single Frame)</strong>: Unsegmentierte Transport-PDU, übertragen vom Sender zum Receiver.\n</li><li><strong>AF (Acknowledgement Frame)</strong>: Bestätigungs-PDU vom Receiver zum Sender mit Ausprägung als negative Bestätigung (<code>AF (Negative Acknowledge)</code>) oder positive Bestätigung (<code>AF (Positive Acknowledge)</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Sequenzablauf stellt ein unsegmentiertes Übertragungsszenario mit anfänglichem Fehlschlag und erfolgreicher Wiederholung dar:</p>\n<ol class=\"fig-list\"><li>Sender initiiert die Übertragung mit einem ersten <code>SF</code> an den Receiver.\n</li><li>Receiver quittiert den fehlerhaften Empfang mit <code>AF (Negative Acknowledge)</code>.\n</li><li>Sender führt einen erneuten Sendeversuch (Retry) durch und sendet den <code>SF</code> erneut an den Receiver.\n</li><li>Receiver bestätigt den erfolgreichen Empfang des wiederholten Frames mit <code>AF (Positive Acknowledge)</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Ablauf definiert das deterministische Fehlerbehebungsverhalten bei aktivierter Bestätigung (<code>FrTpAckType = FRTP_ACK_WITH_RETRY</code>).</p>\n<ul class=\"fig-list\"><li>Bei Empfang von <code>AF (Negative Acknowledge)</code> muss die FrTp-Sendeseite den <code>SF</code> erneut übertragen, sofern die konfigurierte Maximalanzahl an Wiederholungsversuchen (<code>FRTP_MAX_RN</code>) noch nicht erreicht ist.\n</li><li>Erreicht die Anzahl der Wiederholungen <code>FRTP_MAX_RN</code> ohne positiven Empfang, wird der Übertragungsversuch abgebrochen und <code>PduR_FrTpTxConfirmation</code> bzw. <code>PduR_FrTpRxIndication</code> mit entsprechendem Fehlerergebnis an das PDU Router Modul (PduR) gemeldet.\n</li><li>Erst nach Empfang von <code>AF (Positive Acknowledge)</code> gilt die PDU als erfolgreich zugestellt.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-7c63d6315fd9d2f7", "to": "FIG-a6a742e0d6b34db2", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
